contracts/IOrgan.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import './libraries/CoreLibrary.sol';

interface IOrgan {
    enum ParamConstraintType {
        NONE,
        EXACT,
        RANGE,
        SELF,
        WHITELISTED_ADDRESS
    }

    struct ParamConstraintInput {
        uint8 index;
        ParamConstraintType constraintType;
        bytes32 minValue;
        bytes32 maxValue;
        bytes32 exactValue;
    }

    /// @notice Initialize a freshly cloned organ.
    /// @param procedures Addresses that receive permissions on the organ.
    /// @param permissions Permission bitmasks aligned with `procedures`.
    /// @param cid Content identifier describing the organ metadata.
    /// @param entries Initial entries stored on the organ.
    /// @param trustedForwarder ERC-2771 forwarder trusted by the organ.
    function initialize(
        address[] memory procedures,
        bytes2[] memory permissions,
        string memory cid,
        CoreLibrary.Entry[] memory entries,
        address trustedForwarder
    ) external;

    /// @notice Update the metadata CID of the organ.
    /// @param cid New content identifier describing the organ.
    function updateCid(string calldata cid) external;

    /// @notice Append entries to the organ directory.
    /// @param entries Entries to append.
    /// @return indexes Indexes assigned to the newly inserted entries.
    function addEntries(
        CoreLibrary.Entry[] memory entries
    ) external returns (uint256[] memory indexes);

    /// @notice Remove entries from the organ directory.
    /// @param indexes Indexes to remove.
    function removeEntries(uint256[] memory indexes) external;

    /// @notice Replace one entry at a fixed index.
    /// @param index Index of the entry to replace.
    /// @param entry New entry payload stored at `index`.
    function replaceEntry(
        uint256 index,
        CoreLibrary.Entry memory entry
    ) external;

    /// @notice Grant permissions to one address or procedure.
    /// @param permissionAddress Address receiving the permission bitmask.
    /// @param permissionValue Permission bitmask to grant.
    function addPermission(
        address permissionAddress,
        bytes2 permissionValue
    ) external;

    /// @notice Remove every permission bit from one address or procedure.
    /// @param permissionAddress Address whose permissions should be removed.
    function removePermission(address permissionAddress) external;

    /// @notice Replace one permission holder with another.
    /// @param oldPermission Address currently holding the permission.
    /// @param newPermission Address that should receive the permission instead.
    /// @param newPermissionValue Permission bitmask assigned to `newPermission`.
    function replacePermission(
        address oldPermission,
        address newPermission,
        bytes2 newPermissionValue
    ) external;

    /// @notice Configure a whitelist policy for an external call path.
    /// @dev Policies are keyed by `target + selector`. Each policy can constrain calldata
    /// arguments with `NONE`, `EXACT`, `RANGE`, `SELF`, or `WHITELISTED_ADDRESS`.
    /// The whitelist is only consulted by constraints that use `WHITELISTED_ADDRESS`.
    /// @param target The external contract the organ may call.
    /// @param selector The function selector allowed on `target`.
    /// @param constraints The calldata constraints that must be satisfied to execute the call.
    /// @param whitelistedAddresses The addresses accepted by whitelist-based constraints.
    function setCallPolicy(
        address target,
        bytes4 selector,
        ParamConstraintInput[] calldata constraints,
        address[] calldata whitelistedAddresses
    ) external;

    /// @notice Remove a previously configured external call policy.
    /// @param target The external contract whose policy should be removed.
    /// @param selector The function selector whose policy should be removed.
    function removeCallPolicy(address target, bytes4 selector) external;

    /// @notice Execute an external call that has been approved by a whitelist policy.
    /// @dev The organ validates the call against the policy configured for `target + selector`
    /// before forwarding the call. Every configured constraint must pass.
    /// @param target The external contract to call.
    /// @param value The amount of native token to forward with the call.
    /// @param data The encoded calldata forwarded to `target`.
    /// @return result The raw return data produced by the external call.
    function executeWhitelisted(
        address target,
        uint256 value,
        bytes calldata data
    ) external returns (bytes memory result);

    /// @notice Return the core summary of the organ.
    /// @return cid Metadata CID currently attached to the organ.
    /// @return permissionsLength Number of permission entries configured on the organ.
    /// @return entriesLength Number of allocated entry slots.
    /// @return entriesCount Number of active entries.
    /// @return interfaceId ERC-165 interface id implemented by the organ.
    function getOrgan()
        external
        view
        returns (
            string memory cid,
            uint256 permissionsLength,
            uint256 entriesLength,
            uint256 entriesCount,
            bytes4 interfaceId
        );

    /// @notice Find the index of one entry address.
    /// @param addr Address stored in the entry.
    /// @return index Index of the entry associated with `addr`.
    function getEntryIndexForAddress(
        address addr
    ) external view returns (uint256 index);

    /// @notice Return one stored entry.
    /// @param index Index of the entry to read.
    /// @return entry Entry payload stored at `index`.
    function getEntry(
        uint256 index
    ) external view returns (CoreLibrary.Entry memory entry);

    /// @notice Return one permission entry by index.
    /// @param index Index of the permission entry to read.
    /// @return addr Address holding the permission.
    /// @return perms Permission bitmask held by `addr`.
    function getPermission(
        uint256 index
    ) external view returns (address addr, bytes2 perms);

    /// @notice Return the permission bitmask assigned to one address.
    /// @param addr Address to inspect.
    /// @return perms Permission bitmask currently assigned to `addr`.
    function getPermissions(address addr) external view returns (bytes2 perms);

    /// @notice Return summary information about a call policy.
    /// @param target The external contract keyed by the policy.
    /// @param selector The function selector keyed by the policy.
    /// @return enabled Whether the policy exists and is active.
    /// @return constraintsLength The number of parameter constraints configured on the policy.
    /// @return whitelistedAddressesLength The number of addresses stored in the policy whitelist.
    function getCallPolicy(
        address target,
        bytes4 selector
    )
        external
        view
        returns (
            bool enabled,
            uint256 constraintsLength,
            uint256 whitelistedAddressesLength
        );

    /// @notice Return one parameter constraint of a call policy.
    /// @param target The external contract keyed by the policy.
    /// @param selector The function selector keyed by the policy.
    /// @param index The position of the constraint inside the policy.
    /// @return paramIndex The zero-based calldata argument index constrained by this rule.
    /// @return constraintType The type of validation applied to that argument.
    /// @return minValue The lower bound used by range constraints.
    /// @return maxValue The upper bound used by range constraints.
    /// @return exactValue The exact value used by exact-match constraints.
    function getCallPolicyConstraint(
        address target,
        bytes4 selector,
        uint256 index
    )
        external
        view
        returns (
            uint8 paramIndex,
            ParamConstraintType constraintType,
            bytes32 minValue,
            bytes32 maxValue,
            bytes32 exactValue
        );

    /// @notice Check whether an address is present in a call policy whitelist.
    /// @param target The external contract keyed by the policy.
    /// @param selector The function selector keyed by the policy.
    /// @param candidate The address to test against the whitelist.
    /// @return True if `candidate` belongs to the whitelist associated with the policy.
    function isCallPolicyWhitelistedAddress(
        address target,
        bytes4 selector,
        address candidate
    ) external view returns (bool);
}

contracts/MetaGasStation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import '@openzeppelin/contracts/utils/Context.sol';
import '@openzeppelin/contracts/metatx/ERC2771Forwarder.sol';

contract MetaGasStation is ERC2771Forwarder {
    constructor(string memory name) ERC2771Forwarder(name) {}
}

abstract contract ERC2771Recipient is Context {
    address private _trustedForwarder;

    function _setTrustedForwarder(address forwarder) internal virtual {
        _trustedForwarder = forwarder;
    }

    /// @notice Return whether an address is the trusted ERC-2771 forwarder.
    /// @param forwarder The forwarder address to test.
    /// @return True if `forwarder` is trusted by this contract.
    function isTrustedForwarder(
        address forwarder
    ) public view virtual returns (bool) {
        return forwarder == _trustedForwarder;
    }

    /// @notice Return the trusted ERC-2771 forwarder used by this contract.
    /// @return The forwarder allowed to relay signed calls on behalf of users.
    function trustedForwarder() public view virtual returns (address) {
        return _trustedForwarder;
    }

    /**
     * @dev Override for `msg.sender`. Defaults to the original `msg.sender` whenever
     * a call is not performed by the trusted forwarder or the calldata length is less than
     * 20 bytes (an address length).
     */
    function _msgSender() internal view virtual override returns (address) {
        uint256 calldataLength = msg.data.length;
        uint256 contextSuffixLength = _contextSuffixLength();
        if (
            calldataLength >= contextSuffixLength &&
            isTrustedForwarder(msg.sender)
        ) {
            unchecked {
                return
                    address(
                        bytes20(msg.data[calldataLength - contextSuffixLength:])
                    );
            }
        } else {
            return super._msgSender();
        }
    }

    /**
     * @dev Override for `msg.data`. Defaults to the original `msg.data` whenever
     * a call is not performed by the trusted forwarder or the calldata length is less than
     * 20 bytes (an address length).
     */
    function _msgData()
        internal
        view
        virtual
        override
        returns (bytes calldata)
    {
        uint256 calldataLength = msg.data.length;
        uint256 contextSuffixLength = _contextSuffixLength();
        if (
            calldataLength >= contextSuffixLength &&
            isTrustedForwarder(msg.sender)
        ) {
            unchecked {
                return msg.data[:calldataLength - contextSuffixLength];
            }
        } else {
            return super._msgData();
        }
    }

    /**
     * @dev ERC-2771 specifies the context as being a single address (20 bytes).
     */
    function _contextSuffixLength()
        internal
        view
        virtual
        override
        returns (uint256)
    {
        return 20;
    }
}

contracts/Organ.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import './libraries/CoreLibrary.sol';
import './libraries/OrganLibrary.sol';
import './MetaGasStation.sol';
import './IOrgan.sol';
import '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';
import '@openzeppelin/contracts/interfaces/IERC721.sol';
import '@openzeppelin/contracts/interfaces/IERC777.sol';
import '@openzeppelin/contracts/utils/introspection/ERC165.sol';
import {Initializable as InitializableStatic} from '@openzeppelin/contracts/proxy/utils/Initializable.sol';
import '@openzeppelin/contracts/interfaces/IERC777Recipient.sol';
import '@openzeppelin/contracts/interfaces/IERC777Sender.sol';
import '@openzeppelin/contracts/interfaces/IERC721Receiver.sol';
import '@openzeppelin/contracts/interfaces/IERC1155Receiver.sol';

/// @title Organ contract
/// @author Organigram.ai
/// @notice An organ contains a list of entries, a list of assets (tokens) and a set of procedures. A procedure is a contract that can effect changes on organs. An entry can be a document and/or an address (a wallet or a contract).

contract Organ is
    IOrgan,
    ERC165,
    InitializableStatic,
    IERC777Recipient,
    IERC777Sender,
    IERC721Receiver,
    IERC1155Receiver,
    ReentrancyGuard,
    ERC2771Recipient
{
    using CoreLibrary for CoreLibrary.Entry;
    using OrganLibrary for OrganLibrary.OrganData;
    using EnumerableSet for EnumerableSet.AddressSet;

    // Organ data storage.
    OrganLibrary.OrganData internal organData;
    bytes4 constant INTERFACE_ID = type(IOrgan).interfaceId;

    /**
        Organ API.
    */

    constructor() {
        _disableInitializers();
    }

    // Register EIP165 interfaces for introspection.
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC165, IERC165) returns (bool) {
        return
            interfaceId == type(IERC777Recipient).interfaceId ||
            interfaceId == type(IERC777Sender).interfaceId ||
            interfaceId == type(IERC721Receiver).interfaceId ||
            interfaceId == type(IERC1155Receiver).interfaceId ||
            interfaceId == INTERFACE_ID ||
            super.supportsInterface(interfaceId);
    }

    /// @inheritdoc IOrgan
    function initialize(
        address[] memory permissionAddresses,
        bytes2[] memory permissionValues,
        string memory cid,
        CoreLibrary.Entry[] memory entries,
        address forwarder
    ) external override initializer {
        organData.init(permissionAddresses, permissionValues, cid, entries);
        _setTrustedForwarder(forwarder);
    }

    // Assets.

    receive() external payable {
        organData.receiveEther(msg.value, _msgSender());
    }

    function transferEther(address payable to, uint256 value) public nonReentrant {
        organData.transferEther(to, value, _msgSender());
    }

    // Implementing ERC-777 receiver interface.
    function tokensReceived(
        address operator,
        address from,
        address to,
        uint256 amount,
        bytes calldata /*data*/,
        bytes calldata /*operatorData*/
    ) external override {
        organData.receiveCoins(operator, from, to, amount);
    }

    function tokensToSend(
        address operator,
        address,
        address to,
        uint256 amount,
        bytes calldata /*userData*/,
        bytes calldata /*operatorData*/
    ) external override {
        organData.transferCoins(_msgSender(), operator, to, amount);
    }

    function transferCoins(
        address token,
        address,
        address to,
        uint256 amount
    ) external nonReentrant {
        organData.transferCoins(token, _msgSender(), to, amount);
    }

    function transferCollectible(
        address token,
        address,
        address to,
        uint256 tokenId
    ) external nonReentrant {
        organData.transferCollectible(token, _msgSender(), to, tokenId);
    }

    // ERC-721 receiver hook.
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes memory /*data*/
    ) public override returns (bytes4) {
        organData.receiveCollectible(operator, from, tokenId);
        return this.onERC721Received.selector;
    }

    // ERC-1155 receiver hooks.
    function onERC1155Received(
        address,
        address,
        uint256,
        uint256,
        bytes memory
    ) public virtual override returns (bytes4) {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(
        address,
        address,
        uint256[] memory,
        uint256[] memory,
        bytes memory
    ) public virtual override returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    /// @inheritdoc IOrgan
    function updateCid(string calldata cid) external override {
        organData.updateCid(cid, _msgSender());
    }

    /*
        API for Procedure contract.
    */

    /// @inheritdoc IOrgan
    function addEntries(
        CoreLibrary.Entry[] memory entries
    ) external override returns (uint256[] memory indexes) {
        return organData.addEntries(entries, _msgSender());
    }

    /// @inheritdoc IOrgan
    function removeEntries(uint256[] memory indexes) external override {
        organData.removeEntries(indexes, _msgSender());
    }

    /// @inheritdoc IOrgan
    function replaceEntry(
        uint256 index,
        CoreLibrary.Entry memory entry
    ) external override {
        organData.replaceEntry(index, entry, _msgSender());
    }

    // @TODO : Should be plural.
    /// @inheritdoc IOrgan
    function addPermission(
        address permissionAddress,
        bytes2 permissionValue
    ) external override {
        organData.addPermission(
            permissionAddress,
            permissionValue,
            _msgSender()
        );
    }

    // @TODO : Should be plural.
    /// @inheritdoc IOrgan
    function removePermission(address permissionAddress) external override {
        organData.removePermission(permissionAddress, _msgSender());
    }

    /// @inheritdoc IOrgan
    function replacePermission(
        address oldPermissionAddress,
        address newPermissionAddress,
        bytes2 newPermissionValue
    ) external override {
        organData.replacePermission(
            oldPermissionAddress,
            newPermissionAddress,
            newPermissionValue,
            _msgSender()
        );
    }

    /// @inheritdoc IOrgan
    function setCallPolicy(
        address target,
        bytes4 selector,
        IOrgan.ParamConstraintInput[] calldata constraints,
        address[] calldata whitelistedAddresses
    ) external override {
        uint256 constraintsLength = constraints.length;
        OrganLibrary.ParamConstraint[] memory converted = new OrganLibrary.ParamConstraint[](constraintsLength);
        for (uint256 i = 0; i < constraintsLength; i++) {
            converted[i] = OrganLibrary.ParamConstraint({
                index: constraints[i].index,
                constraintType: OrganLibrary.ParamConstraintType(uint8(constraints[i].constraintType)),
                minValue: constraints[i].minValue,
                maxValue: constraints[i].maxValue,
                exactValue: constraints[i].exactValue
            });
        }
        organData.setCallPolicy(
            target,
            selector,
            converted,
            whitelistedAddresses,
            _msgSender()
        );
    }

    /// @inheritdoc IOrgan
    function removeCallPolicy(address target, bytes4 selector) external override {
        organData.removeCallPolicy(target, selector, _msgSender());
    }

    /// @inheritdoc IOrgan
    function executeWhitelisted(
        address target,
        uint256 value,
        bytes calldata data
    ) external override nonReentrant returns (bytes memory result) {
        return organData.executeWhitelisted(target, value, data, _msgSender());
    }

    /*
        Accessors.
    */

    /// @inheritdoc IOrgan
    function getOrgan()
        external
        view
        override
        returns (
            string memory cid,
            uint256 permissionsLength,
            uint256 entriesLength,
            uint256 entriesCount,
            bytes4 interfaceId
        )
    {
        return (
            organData.cid,
            organData.getPermissionsLength(),
            organData.entries.length,
            organData.entriesCount,
            INTERFACE_ID
        );
    }

    /// @inheritdoc IOrgan
    function getEntryIndexForAddress(
        address addr
    ) external view override returns (uint256 index) {
        return organData.addressIndexInEntries[addr];
    }

    /// @inheritdoc IOrgan
    function getEntry(
        uint256 index
    ) external view override returns (CoreLibrary.Entry memory entry) {
        return organData.getEntry(index);
    }

    /// @inheritdoc IOrgan
    function getPermission(
        uint256 index
    ) external view override returns (address addr, bytes2 perms) {
        (addr, perms) = organData.getPermission(index);
        return (addr, perms);
    }

    /// @inheritdoc IOrgan
    function getPermissions(
        address addr
    ) external view override returns (bytes2 perms) {
        return organData.permissions[addr];
    }

    /// @inheritdoc IOrgan
    function getCallPolicy(
        address target,
        bytes4 selector
    )
        external
        view
        override
        returns (
            bool enabled,
            uint256 constraintsLength,
            uint256 whitelistedAddressesLength
        )
    {
        bytes32 policyKey = OrganLibrary._callPolicyKey(target, selector);
        OrganLibrary.CallPolicy storage policy = organData.callPolicies[policyKey];
        return (
            policy.enabled,
            policy.constraints.length,
            organData.callPolicyWhitelistedAddresses[policyKey].length()
        );
    }

    /// @inheritdoc IOrgan
    function getCallPolicyConstraint(
        address target,
        bytes4 selector,
        uint256 index
    )
        external
        view
        override
        returns (
            uint8 paramIndex,
            IOrgan.ParamConstraintType constraintType,
            bytes32 minValue,
            bytes32 maxValue,
            bytes32 exactValue
        )
    {
        bytes32 policyKey = OrganLibrary._callPolicyKey(target, selector);
        OrganLibrary.ParamConstraint storage constraint = organData.callPolicies[policyKey].constraints[index];
        return (
            constraint.index,
            IOrgan.ParamConstraintType(uint8(constraint.constraintType)),
            constraint.minValue,
            constraint.maxValue,
            constraint.exactValue
        );
    }

    /// @inheritdoc IOrgan
    function isCallPolicyWhitelistedAddress(
        address target,
        bytes4 selector,
        address candidate
    ) external view override returns (bool) {
        bytes32 policyKey = OrganLibrary._callPolicyKey(target, selector);
        return organData.callPolicyWhitelistedAddresses[policyKey].contains(candidate);
    }
}

contracts/OrganigramClient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import './Organ.sol';
import './Asset.sol';
import './IAsset.sol';
import './MetaGasStation.sol';
import './libraries/CoreLibrary.sol';
import '@openzeppelin/contracts/utils/introspection/ERC165Checker.sol';
import '@openzeppelin/contracts/proxy/Clones.sol';
import '@openzeppelin/contracts/utils/Address.sol';

contract OrganigramClient is ERC2771Recipient {
    using CoreLibrary for CoreLibrary.Entry;
    address payable public immutable organ; // Cloneable organ implementation.
    address payable public immutable asset; // Cloneable asset implementation.
    address payable public immutable proceduresRegistry; // Organ with the addresses of supported procedures implementations.
    address public immutable owner;

    event organDeployed(address payable organ);
    event assetDeployed(address payable asset);
    event procedureDeployed(
        address payable procedureType,
        address payable procedure
    );

    struct DeployOrganArgs {
        address[] permissionAddresses;
        bytes2[] permissionValues;
        string cid;
        CoreLibrary.Entry[] entries;
        bytes32 salt;
    }
    struct DeployProcedureArgs {
        address payable procedureType;
        bytes data;
        bytes32 salt;
    }
    struct DeployAssetArgs {
        string name;
        string symbol;
        uint256 initialSupply;
        bytes32 salt;
    }

    /// @notice Deploy the client contract together with default organ and asset implementations.
    /// @param cid Metadata CID assigned to the internal procedures registry organ.
    /// @param trustedForwarder ERC-2771 forwarder trusted by freshly deployed clones.
    /// @param salt Deterministic salt used to deploy the procedures registry organ.
    constructor(string memory cid, address trustedForwarder, bytes32 salt) {
        _setTrustedForwarder(trustedForwarder);
        owner = _msgSender();
        organ = payable(address(new Organ()));
        asset = payable(address(new Asset()));

        // Create permissions arguments for the procedures registry organ.
        address[] memory permissionAddresses = new address[](2);
        bytes2[] memory permissionValues = new bytes2[](2);

        permissionAddresses[0] = owner; // Set the sender as default admin...
        permissionValues[0] = bytes2(0xffff); // ...with all permissions.
        permissionAddresses[1] = address(this); // Allow controlled registry updates via registerProcedures().
        permissionValues[1] = bytes2(0x0004); // PERMISSION_ADD_ENTRIES.

        CoreLibrary.Entry[] memory emptyEntries = new CoreLibrary.Entry[](0);

        proceduresRegistry = deployOrgan(
            permissionAddresses,
            permissionValues,
            cid,
            emptyEntries,
            salt
        );
    }

    /// @notice Deploy a single organ clone and initialize it.
    /// @param _permissionAddresses Addresses receiving permissions on the organ.
    /// @param _permissionValues Permission bitmasks aligned with `_permissionAddresses`.
    /// @param cid Metadata CID assigned to the deployed organ.
    /// @param entries Initial entries stored on the organ.
    /// @param salt Deterministic clone salt.
    /// @return clone Address of the deployed organ clone.
    function deployOrgan(
        address[] memory _permissionAddresses,
        bytes2[] memory _permissionValues,
        string memory cid,
        CoreLibrary.Entry[] memory entries,
        bytes32 salt
    ) public returns (address payable clone) {
        require(
            _permissionAddresses.length == _permissionValues.length,
            'LengthMismatch'
        );

        // If no permissions are provided, set the sender as admin with all permissions.
        if (_permissionAddresses.length == 0) {
            _permissionAddresses = new address[](1);
            _permissionValues = new bytes2[](1);
            _permissionAddresses[0] = _msgSender();
            _permissionValues[0] = bytes2(0xffff);
        }

        // Clone organ and initialize it.
        clone = payable(Clones.cloneDeterministic(organ, salt));
        Organ(clone).initialize(
            _permissionAddresses,
            _permissionValues,
            cid,
            entries,
            trustedForwarder()
        );
        emit organDeployed(clone);
        return clone;
    }

    /// @notice Deploy several organ clones in one call.
    /// @param batch Organ deployment payloads.
    /// @return clones Addresses of the deployed organ clones.
    function deployOrgans(
        DeployOrganArgs[] memory batch
    ) public returns (address payable[] memory clones) {
        clones = new address payable[](batch.length);

        for (uint256 i = 0; i < batch.length; i++) {
            clones[i] = deployOrgan(
                batch[i].permissionAddresses,
                batch[i].permissionValues,
                batch[i].cid,
                batch[i].entries,
                batch[i].salt
            );
        }
        return clones;
    }

    /// @notice Deploy a single asset clone and initialize it as an ERC-20 token.
    /// @param name Token name.
    /// @param symbol Token symbol.
    /// @param initialSupply Initial token supply minted to the caller.
    /// @param salt Deterministic clone salt.
    /// @return clone Address of the deployed asset clone.
    function deployAsset(
        string memory name,
        string memory symbol,
        uint256 initialSupply,
        bytes32 salt
    ) public returns (address payable clone) {
        clone = payable(Clones.cloneDeterministic(address(asset), salt));
        IAsset(clone).initialize(name, symbol, _msgSender(), initialSupply);

        emit assetDeployed(clone);
        return clone;
    }

    /// @notice Deploy several asset clones in one call.
    /// @param batch Asset deployment payloads.
    /// @return clones Addresses of the deployed asset clones.
    function deployAssets(
        DeployAssetArgs[] memory batch
    ) public returns (address payable[] memory clones) {
        clones = new address payable[](batch.length);

        for (uint256 i = 0; i < batch.length; i++) {
            clones[i] = deployAsset(
                batch[i].name,
                batch[i].symbol,
                batch[i].initialSupply,
                batch[i].salt
            );
        }
        return clones;
    }

    /// @notice Deploy one procedure clone from a registered procedure implementation.
    /// @param procedureType Registered procedure implementation to clone.
    /// @param data Optional initialization calldata executed immediately after deployment.
    /// @param salt Deterministic clone salt.
    /// @return procedure Address of the deployed procedure clone.
    function deployProcedure(
        address payable procedureType,
        bytes memory data,
        bytes32 salt
    ) public returns (address payable procedure) {
        require(data.length > 0, 'Missing initialization data.');
        require(
            ERC165Checker.supportsInterface(procedureType, 0x71dbd330),
            'Not a procedure.'
        );
        require(
            Organ(proceduresRegistry).getEntryIndexForAddress(procedureType) >
                0,
            'Procedure not found.'
        );
        procedure = payable(Clones.cloneDeterministic(procedureType, salt));
        emit procedureDeployed(procedureType, procedure);
        bytes memory initReturnData = Address.functionCall(procedure, data);
        require(initReturnData.length == 0, 'Unexpected initialization result.');
        return procedure;
    }

    /// @notice Deploy several procedure clones in one call.
    /// @param batch Procedure deployment payloads.
    /// @return created Addresses of the deployed procedure clones.
    function deployProcedures(
        DeployProcedureArgs[] memory batch
    ) public returns (address payable[] memory created) {
        created = new address payable[](batch.length);

        for (uint256 i = 0; i < batch.length; i++) {
            created[i] = deployProcedure(
                batch[i].procedureType,
                batch[i].data,
                batch[i].salt
            );
        }
        return created;
    }

    /// @notice Deploy a complete organigram in one transaction.
    /// @param organBatch Organ deployment payloads.
    /// @param assetBatch Asset deployment payloads.
    /// @param procedureBatch Procedure deployment payloads.
    /// @return organsDeployed Addresses of the deployed organs.
    /// @return assetsDeployed Addresses of the deployed assets.
    /// @return proceduresDeployed Addresses of the deployed procedures.
    function deployOrganigram(
        DeployOrganArgs[] memory organBatch,
        DeployAssetArgs[] memory assetBatch,
        DeployProcedureArgs[] memory procedureBatch
    )
        public
        returns (
            address payable[] memory organsDeployed,
            address payable[] memory assetsDeployed,
            address payable[] memory proceduresDeployed
        )
    {
        organsDeployed = deployOrgans(organBatch);
        assetsDeployed = deployAssets(assetBatch);
        proceduresDeployed = deployProcedures(procedureBatch);
        return (organsDeployed, assetsDeployed, proceduresDeployed);
    }

    /// @notice Register supported procedure implementations in the procedures registry.
    /// @param entries Registry entries that point to valid procedure implementations.
    function registerProcedures(CoreLibrary.Entry[] memory entries) external {
        require(_msgSender() == owner, 'Not authorized.');
        // Only valid procedures
        for (uint256 i; i < entries.length; ++i) {
            require(
                ERC165Checker.supportsInterface(entries[i].addr, 0x71dbd330),
                'An entry in parameters is not a valid procedure.'
            );
        }
        uint256[] memory indexes = Organ(proceduresRegistry).addEntries(entries);
        require(indexes.length == entries.length, 'Registry update failed.');
    }
}

contracts/Procedure.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import './libraries/ProcedureLibrary.sol';
import './MetaGasStation.sol';
import '@openzeppelin/contracts/utils/introspection/ERC165.sol';
import '@openzeppelin/contracts/utils/cryptography/ECDSA.sol';
import '@openzeppelin/contracts/utils/cryptography/EIP712.sol';
import {Initializable as InitializableStatic} from '@openzeppelin/contracts/proxy/utils/Initializable.sol';
import '@openzeppelin/contracts/utils/ReentrancyGuard.sol';

/*
    A procedure defines a set of operations compiled in a proposal.
    The procedure dictates the way the proposal can be applied.
*/
contract Procedure is
    ERC165,
    InitializableStatic,
    ReentrancyGuard,
    ERC2771Recipient,
    EIP712
{
    using ProcedureLibrary for ProcedureLibrary.ProcedureData;
    using ProcedureLibrary for ProcedureLibrary.Operation;
    ProcedureLibrary.ProcedureData internal procedureData;
    bytes4 public constant INTERFACE_ID = 0x71dbd330;
    bytes32 internal constant OPERATION_TYPEHASH =
        keccak256(
            'Operation(uint256 index,address target,bytes data,uint256 value)'
        );
    bytes32 internal constant PROPOSAL_TYPEHASH =
        keccak256(
            'Proposal(string cid,bytes32 operationsHash,uint256 nonce,uint256 deadline)'
        );
    bytes32 internal constant PRESENT_PROPOSAL_TYPEHASH =
        keccak256(
            'PresentProposal(uint256 proposalKey,uint256 nonce,uint256 deadline)'
        );
    bytes32 internal constant BLOCK_PROPOSAL_TYPEHASH =
        keccak256(
            'BlockProposal(uint256 proposalKey,string reason,uint256 nonce,uint256 deadline)'
        );
    bytes32 internal constant APPLY_PROPOSAL_TYPEHASH =
        keccak256(
            'ApplyProposal(uint256 proposalKey,uint256 nonce,uint256 deadline)'
        );

    /**
        Modifiers.
    */
    modifier onlyInOrgan(address payable organAddress) {
        require(
            ProcedureLibrary.isInOrgan(organAddress, _msgSender()),
            'Not authorized'
        );
        _;
    }

    modifier onlyDeciders() {
        require(
            ProcedureLibrary.isInOrgan(procedureData.deciders, _msgSender()),
            'Not authorized'
        );
        _;
    }

    /**
        Procedure constructor.
    */
    constructor() EIP712('Organigram Procedure', '1') {
        _disableInitializers();
    }

    // Register EIP165 interfaces for introspection.
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override returns (bool) {
        // @todo : Use type(IProcedure).interfaceId
        return
            interfaceId == INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    function initialize(
        string memory _cid,
        address payable _proposers,
        address payable _moderators,
        address payable _deciders,
        bool _withModeration,
        address _trustedForwarder
    ) public virtual initializer {
        procedureData.init(
            _cid,
            _proposers,
            _moderators,
            _deciders,
            _withModeration,
            _trustedForwarder,
            _msgSender()
        );
        _setTrustedForwarder(_trustedForwarder);
    }

    /**
        Public API : Procedure Cid and Admin.
    */
    function updateCid(string memory cid) public {
        procedureData.updateCid(cid, _msgSender());
    }

    function updateAdmin(address payable admin) public {
        procedureData.updateAdmin(admin, _msgSender());
    }

    /**
        Public API : Proposals creation and update.
    */
    function propose(
        string memory cid,
        ProcedureLibrary.Operation[] memory operations
    ) public virtual returns (uint256 proposalKey) {
        return procedureData.propose(cid, operations, _msgSender());
    }

    function proposeBySig(
        string calldata cid,
        ProcedureLibrary.Operation[] calldata operations,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual returns (uint256 proposalKey) {
        bytes32 operationsHash = _hashOperations(operations);
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    PROPOSAL_TYPEHASH,
                    keccak256(bytes(cid)),
                    operationsHash,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        return procedureData.propose(cid, operations, signer);
    }

    /// @notice The procedure can override this method.
    function blockProposal(
        uint256 proposalKey,
        string calldata reason
    ) public virtual {
        procedureData.blockProposal(proposalKey, reason, _msgSender());
    }

    function blockProposalBySig(
        uint256 proposalKey,
        string calldata reason,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual {
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    BLOCK_PROPOSAL_TYPEHASH,
                    proposalKey,
                    keccak256(bytes(reason)),
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        procedureData.blockProposal(proposalKey, reason, signer);
    }

    /// @notice When moderation is enabled, moderators must accept the proposal.
    function presentProposal(uint256 proposalKey) public virtual {
        procedureData.presentProposal(proposalKey, _msgSender());
    }

    function presentProposalBySig(
        uint256 proposalKey,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual {
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    PRESENT_PROPOSAL_TYPEHASH,
                    proposalKey,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        procedureData.presentProposal(proposalKey, signer);
    }

    /// @notice The procedure calls this method directly to adopt and apply a proposal.
    function _adoptProposal(uint256 proposalKey) internal virtual nonReentrant {
        procedureData._adoptProposal(proposalKey);
    }

    /// @notice The procedure calls this method directly to reject a proposal.
    function _rejectProposal(uint256 proposalKey) internal virtual nonReentrant {
        procedureData._rejectProposal(proposalKey);
    }

    /// @notice Apply proposal.
    function applyProposal(uint256 proposalKey) public virtual nonReentrant {
        procedureData.applyProposal(proposalKey);
    }

    function applyProposalBySig(
        uint256 proposalKey,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual nonReentrant {
        _recoverTypedSigner(
            keccak256(
                abi.encode(
                    APPLY_PROPOSAL_TYPEHASH,
                    proposalKey,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        procedureData.applyProposal(proposalKey);
    }

    /*
        Accessors.
    */
    function getProcedure()
        public
        view
        returns (
            string memory cid,
            address payable proposers,
            address payable moderators,
            address payable deciders,
            bool withModeration,
            uint256 proposalsLength,
            bytes4 interfaceId
        )
    {
        return (
            procedureData.cid,
            procedureData.proposers,
            procedureData.moderators,
            procedureData.deciders,
            procedureData.withModeration,
            procedureData.proposalsLength,
            INTERFACE_ID
        );
    }

    function getProposal(
        uint256 proposalKey
    ) public view returns (ProcedureLibrary.Proposal memory) {
        return procedureData.proposals[proposalKey];
    }

    function getNonce(address account) public view returns (uint256) {
        return procedureData.nonces[account];
    }

    function _recoverTypedSigner(
        bytes32 structHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) internal returns (address signer) {
        require(deadline >= block.timestamp, 'Signature expired');
        signer = ECDSA.recover(_hashTypedDataV4(structHash), signature);
        require(procedureData.nonces[signer] == nonce, 'Invalid nonce');
        procedureData.nonces[signer] = nonce + 1;
    }

    function _hashOperation(
        ProcedureLibrary.Operation memory operation
    ) internal pure returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    OPERATION_TYPEHASH,
                    operation.index,
                    operation.target,
                    keccak256(operation.data),
                    operation.value
                )
            );
    }

    function _hashOperations(
        ProcedureLibrary.Operation[] calldata operations
    ) internal pure returns (bytes32) {
        bytes32[] memory operationHashes = new bytes32[](operations.length);
        for (uint256 i = 0; i < operations.length; i++) {
            operationHashes[i] = _hashOperation(operations[i]);
        }
        return keccak256(abi.encodePacked(operationHashes));
    }
}

