contracts/libraries/OrganLibrary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

/*
    Organigram Protocol - Organ library.
    This library holds the logic to manage a simple organ.
*/

import './CoreLibrary.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';
import '@openzeppelin/contracts/interfaces/IERC721.sol';
import '@openzeppelin/contracts/interfaces/IERC777.sol';
import '@openzeppelin/contracts/interfaces/IERC1155.sol';

library OrganLibrary {
    using SafeERC20 for IERC20;
    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.Bytes32Set;
    using CoreLibrary for CoreLibrary.Entry;
    bytes2 public constant PERMISSION_ADD_PERMISSIONS = 0x0001;
    bytes2 public constant PERMISSION_REMOVE_PERMISSIONS = 0x0002;
    bytes2 public constant PERMISSION_ADD_ENTRIES = 0x0004;
    bytes2 public constant PERMISSION_REMOVE_ENTRIES = 0x0008;
    bytes2 public constant PERMISSION_UPDATE_METADATA = 0x0010;
    bytes2 public constant PERMISSION_DEPOSIT_ETHER = 0x0020;
    bytes2 public constant PERMISSION_WITHDRAW_ETHER = 0x0040;
    bytes2 public constant PERMISSION_DEPOSIT_COINS = 0x0080;
    bytes2 public constant PERMISSION_WITHDRAW_COINS = 0x0100;
    bytes2 public constant PERMISSION_DEPOSIT_COLLECTIBLES = 0x0200;
    bytes2 public constant PERMISSION_WITHDRAW_COLLECTIBLES = 0x0400;
    bytes2 public constant PERMISSION_EXECUTE_WHITELISTED = 0x0800;
    bytes2 public constant PERMISSION_MANAGE_EXECUTION_WHITELIST = 0x1000;

    /*
        Entries are sets of addresses, contracts or documents.
    */
    enum ParamConstraintType {
        NONE,
        EXACT,
        RANGE,
        SELF,
        WHITELISTED_ADDRESS
    }

    struct ParamConstraint {
        uint8 index;
        ParamConstraintType constraintType;
        bytes32 minValue;
        bytes32 maxValue;
        bytes32 exactValue;
    }

    struct CallPolicy {
        address target;
        bytes4 selector;
        bool enabled;
        ParamConstraint[] constraints;
    }

    struct OrganData {
        string cid;
        CoreLibrary.Entry[] entries;
        uint256 entriesCount;
        EnumerableSet.AddressSet permissionAddresses;
        mapping(address => bytes2) permissions;
        mapping(address => uint256) addressIndexInEntries;
        EnumerableSet.Bytes32Set callPolicyKeys;
        mapping(bytes32 => CallPolicy) callPolicies;
        mapping(bytes32 => EnumerableSet.AddressSet) callPolicyWhitelistedAddresses;
    }

    /*
        Events.
    */
    event cidUpdated(address from, string cid);
    event adminUpdated(address from, address admin);
    event permissionAdded(
        address from,
        address permissionAddress,
        bytes2 permissionValue
    );
    event permissionRemoved(address from, address permissionAddress);
    event collectibleTransferred(address operator, address to, uint256 tokenId);
    event collectibleReceived(address operator, address from, uint256 tokenId);
    event coinsTransferred(
        address operator,
        address from,
        address to,
        uint256 amount
    );
    event coinsReceived(
        address operator,
        address from,
        address to,
        uint256 amount
    );
    event etherTransferred(address from, address to, uint256 amount);
    event etherReceived(address from, uint256 amount);
    event entryAdded(address from, uint256 index, address addr, string cid);
    event entryRemoved(address from, uint256 index);
    event callPolicySet(address indexed caller, address indexed target, bytes4 indexed selector);
    event callPolicyRemoved(address indexed caller, address indexed target, bytes4 indexed selector);
    event callPolicyWhitelistedAddressAdded(bytes32 indexed policyKey, address indexed candidate);
    event callPolicyWhitelistedAddressRemoved(bytes32 indexed policyKey, address indexed candidate);
    event whitelistedExecution(
        address indexed caller,
        address indexed target,
        bytes4 indexed selector,
        uint256 value
    );

    error LengthMismatch();
    error ZeroAddress();
    error DuplicatePermission(address perm);
    error InvalidTarget();
    error InvalidSelector();
    error CallPolicyNotFound(bytes32 policyKey);
    error InvalidConstraintIndex(uint256 index);
    error UnsupportedCallDataLength();
    error ConstraintViolation(uint256 index);
    error InvalidEntryIndex(uint256 index);

    /*
        Modifier.
    */
    modifier onlyPerm(
        OrganData storage self,
        bytes2 permission,
        address caller
    ) {
        require(
            self.permissions[caller] & permission == permission ||
                self.permissions[address(0)] & permission == permission,
            'Not authorized.'
        );
        _;
    }

    /*
        Constructor.
    */
    function init(
        OrganData storage self,
        address[] memory _permissionAddresses,
        bytes2[] memory _permissionValues,
        string memory cid,
        CoreLibrary.Entry[] memory entries
    ) public {
        // Initializing cid.
        self.cid = cid;

        // Reserve index O for empty Entry.
        self.entries.push(CoreLibrary.Entry(address(0), string('')));

        // Setting the permissions.
        if (_permissionAddresses.length != _permissionValues.length)
            revert LengthMismatch();

        for (uint256 i = 0; i < _permissionAddresses.length; i++) {
            address p = _permissionAddresses[i];
            if (p == address(0)) revert ZeroAddress();
            if (!self.permissionAddresses.add(p)) revert DuplicatePermission(p);

            self.permissions[p] = _permissionValues[i];
        }

        // Adding entries.
        for (uint256 i = 0; i < entries.length; i++) {
            // If the entry has an address, we check that the address has not been used before.
            if (entries[i].addr != address(0)) {
                require(
                    self.addressIndexInEntries[entries[i].addr] == 0,
                    'Duplicate record.'
                );
            }
            self.entries.push(entries[i]);
            if (entries[i].addr != address(0)) {
                self.addressIndexInEntries[entries[i].addr] = self.entries.length - 1;
            }
            self.entriesCount++;
        }
    }


    function _callPolicyKey(
        address target,
        bytes4 selector
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(target, selector));
    }

    function _clearCallPolicyStorage(
        OrganData storage self,
        bytes32 policyKey
    ) internal {
        delete self.callPolicies[policyKey].constraints;
        uint256 length = self.callPolicyWhitelistedAddresses[policyKey].length();
        for (uint256 i = length; i > 0; i--) {
            address candidate = self.callPolicyWhitelistedAddresses[policyKey].at(i - 1);
            bool removed = self.callPolicyWhitelistedAddresses[policyKey].remove(candidate);
            assert(removed);
            emit callPolicyWhitelistedAddressRemoved(policyKey, candidate);
        }
    }

    function _readWord(
        bytes calldata data,
        uint256 index
    ) internal pure returns (bytes32 word) {
        uint256 start = 4 + index * 32;
        if (data.length < start + 32) revert InvalidConstraintIndex(index);
        assembly {
            word := calldataload(add(data.offset, start))
        }
    }

    function _asAddress(bytes32 word) internal pure returns (address) {
        return address(uint160(uint256(word)));
    }

    function _selector(bytes calldata data) internal pure returns (bytes4 selector) {
        if (data.length < 4) revert UnsupportedCallDataLength();
        assembly {
            selector := shr(224, calldataload(data.offset))
        }
    }

    function _entryExists(
        OrganData storage self,
        uint256 index
    ) internal view returns (bool) {
        if (index == 0 || index >= self.entries.length) return false;
        CoreLibrary.Entry storage entry = self.entries[index];
        return entry.addr != address(0) || bytes(entry.cid).length != 0;
    }

    function _performCall(
        address target,
        uint256 value,
        bytes calldata data
    ) internal returns (bytes memory result) {
        (bool success, bytes memory callResult) = target.call{value: value}(data);
        if (!success) {
            assembly {
                revert(add(callResult, 32), mload(callResult))
            }
        }
        return callResult;
    }

    function _validateConstraint(
        OrganData storage self,
        bytes32 policyKey,
        ParamConstraint storage constraint,
        bytes calldata data
    ) internal view {
        if (constraint.constraintType == ParamConstraintType.NONE) {
            return;
        }

        bytes32 word = _readWord(data, constraint.index);
        if (constraint.constraintType == ParamConstraintType.EXACT) {
            if (word != constraint.exactValue) revert ConstraintViolation(constraint.index);
            return;
        }
        if (constraint.constraintType == ParamConstraintType.RANGE) {
            uint256 value = uint256(word);
            if (
                value < uint256(constraint.minValue) ||
                value > uint256(constraint.maxValue)
            ) revert ConstraintViolation(constraint.index);
            return;
        }
        if (constraint.constraintType == ParamConstraintType.SELF) {
            if (_asAddress(word) != address(this)) revert ConstraintViolation(constraint.index);
            return;
        }
        if (constraint.constraintType == ParamConstraintType.WHITELISTED_ADDRESS) {
            if (!self.callPolicyWhitelistedAddresses[policyKey].contains(_asAddress(word))) {
                revert ConstraintViolation(constraint.index);
            }
            return;
        }
    }

    function updateCid(
        OrganData storage self,
        string memory cid,
        address caller
    ) public onlyPerm(self, PERMISSION_UPDATE_METADATA, caller) {
        self.cid = cid;
        emit cidUpdated(caller, cid);
    }

    function setCallPolicy(
        OrganData storage self,
        address target,
        bytes4 selector,
        ParamConstraint[] memory constraints,
        address[] memory whitelistedAddresses,
        address caller
    ) public onlyPerm(self, PERMISSION_MANAGE_EXECUTION_WHITELIST, caller) {
        if (target == address(0)) revert InvalidTarget();
        if (selector == bytes4(0)) revert InvalidSelector();
        bytes32 policyKey = _callPolicyKey(target, selector);
        if (!self.callPolicyKeys.contains(policyKey)) {
            bool added = self.callPolicyKeys.add(policyKey);
            assert(added);
        } else {
            _clearCallPolicyStorage(self, policyKey);
        }
        CallPolicy storage policy = self.callPolicies[policyKey];
        policy.target = target;
        policy.selector = selector;
        policy.enabled = true;
        for (uint256 i = 0; i < constraints.length; i++) {
            policy.constraints.push(constraints[i]);
        }
        for (uint256 i = 0; i < whitelistedAddresses.length; i++) {
            if (self.callPolicyWhitelistedAddresses[policyKey].add(whitelistedAddresses[i])) {
                emit callPolicyWhitelistedAddressAdded(policyKey, whitelistedAddresses[i]);
            }
        }
        emit callPolicySet(caller, target, selector);
    }

    function removeCallPolicy(
        OrganData storage self,
        address target,
        bytes4 selector,
        address caller
    ) public onlyPerm(self, PERMISSION_MANAGE_EXECUTION_WHITELIST, caller) {
        bytes32 policyKey = _callPolicyKey(target, selector);
        if (!self.callPolicyKeys.contains(policyKey)) revert CallPolicyNotFound(policyKey);
        _clearCallPolicyStorage(self, policyKey);
        delete self.callPolicies[policyKey];
        bool removed = self.callPolicyKeys.remove(policyKey);
        assert(removed);
        emit callPolicyRemoved(caller, target, selector);
    }

    function executeWhitelisted(
        OrganData storage self,
        address target,
        uint256 value,
        bytes calldata data,
        address caller
    ) public onlyPerm(self, PERMISSION_EXECUTE_WHITELISTED, caller) returns (bytes memory result) {
        bytes4 selector = _selector(data);
        bytes32 policyKey = _callPolicyKey(target, selector);
        CallPolicy storage policy = self.callPolicies[policyKey];
        if (!policy.enabled) revert CallPolicyNotFound(policyKey);
        for (uint256 i = 0; i < policy.constraints.length; i++) {
            _validateConstraint(self, policyKey, policy.constraints[i], data);
        }
        result = _performCall(target, value, data);
        emit whitelistedExecution(caller, target, selector, value);
    }

    /*
        Assets management.
    */
    function transferCollectible(
        OrganData storage self,
        address token,
        address caller,
        address to,
        uint256 tokenId
    ) public onlyPerm(self, PERMISSION_WITHDRAW_COLLECTIBLES, caller) {
        // @note Organ must be the owner, approved, or operator of ERC-721.
        IERC721(token).safeTransferFrom(address(this), to, tokenId);
        emit collectibleTransferred(caller, to, tokenId);
    }

    function receiveCollectible(
        OrganData storage self,
        address operator,
        address from,
        uint256 tokenId
    ) public onlyPerm(self, PERMISSION_DEPOSIT_COLLECTIBLES, from) {
        emit collectibleReceived(operator, from, tokenId);
    }

    function transferCoins(
        OrganData storage self,
        address token,
        address caller,
        address to,
        uint256 amount
    ) public onlyPerm(self, PERMISSION_WITHDRAW_COINS, caller) {
        IERC20(token).safeTransfer(to, amount);
        emit coinsTransferred(caller, address(this), to, amount);
    }

    function receiveCoins(
        OrganData storage self,
        address operator,
        address from,
        address to,
        uint256 amount
    ) public onlyPerm(self, PERMISSION_DEPOSIT_COINS, from) {
        emit coinsReceived(operator, from, to, amount);
    }

    function transferEther(
        OrganData storage self,
        address payable to,
        uint256 amount,
        address from
    ) internal onlyPerm(self, PERMISSION_WITHDRAW_ETHER, from) {
        (bool success, ) = to.call{value: amount}('');
        require(success, 'Transfer failed.');
        emit etherTransferred(from, to, amount);
    }

    function receiveEther(
        OrganData storage self,
        uint256 value,
        address from
    ) public onlyPerm(self, PERMISSION_DEPOSIT_ETHER, from) {
        emit etherReceived(from, value);
    }

    /*
        Procedures management.
    */
    function removePermission(
        OrganData storage self,
        address permissionAddress,
        address caller
    ) public onlyPerm(self, PERMISSION_REMOVE_PERMISSIONS, caller) {
        // Check address is already there.
        require(
            self.permissionAddresses.contains(permissionAddress),
            'Record not found.'
        );
        // Remove from Procedures set.
        bool removed = self.permissionAddresses.remove(permissionAddress);
        assert(removed);
        self.permissions[permissionAddress] = bytes2(0);
        emit permissionRemoved(caller, permissionAddress);
    }

    function addPermission(
        OrganData storage self,
        address permissionAddress,
        bytes2 permissionValue,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_ADD_PERMISSIONS, caller)
    {
        if (permissionAddress == address(0)) revert ZeroAddress();
        // Check new address is not already there.
        require(
            !self.permissionAddresses.contains(permissionAddress),
            'Duplicate record.'
        );
        // Check new address has permissions.
        require(permissionValue != 0x0000, 'Wrong permissions set.');

        // Store permissions.
        bool added = self.permissionAddresses.add(permissionAddress);
        assert(added);
        self.permissions[permissionAddress] = permissionValue;
        emit permissionAdded(caller, permissionAddress, permissionValue);
    }

    function replacePermission(
        OrganData storage self,
        address oldPermissionAddress,
        address newPermissionAddress,
        bytes2 newPermissionValue,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_REMOVE_PERMISSIONS, caller)
        onlyPerm(self, PERMISSION_ADD_PERMISSIONS, caller)
    {
        // Check old address will be removable before adding.
        require(
            self.permissionAddresses.contains(oldPermissionAddress),
            'Record not found.'
        );
        // Check new address has permissions.
        require(newPermissionValue > 0, 'Wrong permissions set.');
        if (newPermissionAddress == address(0)) revert ZeroAddress();

        // Check if we are replacing a master with another, or updating permissions.
        if (oldPermissionAddress != newPermissionAddress) {
            addPermission(
                self,
                newPermissionAddress,
                newPermissionValue,
                caller
            );
            removePermission(self, oldPermissionAddress, caller);
        } else {
            // Update permissions.
            self.permissions[newPermissionAddress] = newPermissionValue;
        }
        // Trigger events.
        emit permissionRemoved(caller, oldPermissionAddress);
        emit permissionAdded(caller, newPermissionAddress, newPermissionValue);
    }

    /**
        Entries management.
    */
    function addEntries(
        OrganData storage self,
        CoreLibrary.Entry[] memory entries,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_ADD_ENTRIES, caller)
        returns (uint256[] memory indexes)
    {
        require(entries.length > 0, 'No entries specified.');
        // uint256 memory initialGas = gasleft();
        indexes = new uint256[](entries.length);

        for (uint256 i = 0; i < entries.length; i++) {
            // If the entry has an address, we check that the address has not been used before.
            if (entries[i].addr != address(0)) {
                require(
                    self.addressIndexInEntries[entries[i].addr] == 0,
                    'Duplicate record.'
                );
            }
            // Adding the entry.
            self.entries.push(entries[i]);
            // Registering entry position relative to its address.
            indexes[i] = self.entries.length - 1;
            if (entries[i].addr != address(0)) {
                self.addressIndexInEntries[entries[i].addr] = indexes[i];
            }
            // Incrementing entries counter.
            self.entriesCount++;
            emit entryAdded(
                caller,
                indexes[i],
                entries[i].addr,
                entries[i].cid
            );
        }

        // Registering the address as active
        return indexes;
    }

    function removeEntries(
        OrganData storage self,
        uint256[] memory indexes,
        address caller
    ) public onlyPerm(self, PERMISSION_REMOVE_ENTRIES, caller) {
        for (uint256 i = 0; i < indexes.length; i++) {
            if (!_entryExists(self, indexes[i])) revert InvalidEntryIndex(indexes[i]);
            address addr = self.entries[indexes[i]].addr;
            delete self.entries[indexes[i]];
            self.entriesCount--;
            // Deleting entry index.
            if (addr != address(0)) self.addressIndexInEntries[addr] = 0;
            // Logging event.
            emit entryRemoved(caller, indexes[i]);
        }
    }

    function replaceEntry(
        OrganData storage self,
        uint256 index,
        CoreLibrary.Entry memory entry,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_REMOVE_ENTRIES, caller)
        onlyPerm(self, PERMISSION_ADD_ENTRIES, caller)
    {
        if (!_entryExists(self, index)) revert InvalidEntryIndex(index);

        address previousAddress = self.entries[index].addr;

        // Check that the replacing address is not already registered elsewhere.
        if (entry.addr != address(0)) {
            require(
                self.addressIndexInEntries[entry.addr] == 0 ||
                    self.addressIndexInEntries[entry.addr] == index,
                'Duplicate record.'
            );
        }
        if (previousAddress != address(0)) {
            self.addressIndexInEntries[previousAddress] = 0;
        }
        emit entryRemoved(caller, index);

        self.entries[index] = entry;

        if (entry.addr != address(0)) {
            self.addressIndexInEntries[entry.addr] = index;
        }
        emit entryAdded(caller, index, entry.addr, entry.cid);
    }

    function getPermissionsLength(
        OrganData storage self
    ) public view returns (uint256 length) {
        return self.permissionAddresses.length();
    }

    function getPermission(
        OrganData storage self,
        uint256 index
    ) public view returns (address addr, bytes2 perms) {
        addr = self.permissionAddresses.at(index);
        perms = self.permissions[addr];
        return (addr, perms);
    }

    function getEntry(
        OrganData storage self,
        uint256 index
    ) public view returns (CoreLibrary.Entry storage) {
        return self.entries[index];
    }
}

contracts/libraries/ProcedureLibrary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import '../IOrgan.sol';

/*
    Organigram Protocol - Procedure library.
    This library holds the logic common to all procedures.

    A procedure can affect an organ by :
    - Adding, removing, replacing entries.
    - Adding, removing, replacing procedures.
    - Withdrawing funds and transferring them to another organ.
    The procedure can process a batch of operations in a proposal.
*/

library ProcedureLibrary {
    struct ProcedureData {
        string cid;
        address payable proposers;
        address payable moderators;
        address payable deciders;
        address payable admin;
        mapping(address => uint256) nonces;
        mapping(uint256 => Proposal) proposals;
        uint256 proposalsLength;
        bool withModeration;
        address forwarder;
        address caller;
    }

    struct Proposal {
        address payable creator;
        string cid;
        string blockReason;
        bool presented;
        bool blocked;
        bool adopted;
        bool applied;
        Operation[] operations;
    }

    struct Operation {
        uint256 index;
        address payable target;
        bytes data;
        uint256 value;
        bool processed;
    }

    /**
        Modifiers.
    */
    modifier onlyInOrgan(address payable organAddress, address sender) {
        require(isInOrgan(organAddress, sender), 'Not authorized.');
        _;
    }

    modifier onlyNewProposal(ProcedureData storage self, uint256 proposalKey) {
        require(
            !self.proposals[proposalKey].presented &&
                !self.proposals[proposalKey].adopted &&
                !self.proposals[proposalKey].applied &&
                !self.proposals[proposalKey].blocked,
            'Not authorized'
        );
        _;
    }

    modifier onlyAdoptedProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) {
        require(
            self.proposals[proposalKey].adopted &&
                !self.proposals[proposalKey].applied &&
                !self.proposals[proposalKey].blocked,
            'Not authorized'
        );
        _;
    }

    modifier onlyPresentedProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) {
        require(
            self.proposals[proposalKey].presented &&
                !self.proposals[proposalKey].adopted &&
                !self.proposals[proposalKey].applied &&
                !self.proposals[proposalKey].blocked,
            'Not authorized'
        );
        _;
    }

    /**
        Events.
    */

    event CidUpdated(address from, string cid);
    event AdminUpdated(address from, address admin);
    event ProposalCreated(address indexed creator, uint256 indexed proposalKey);
    event ProposalBlocked(
        address indexed moderator,
        uint256 indexed proposalKey,
        string reason
    );
    event ProposalPresented(
        address indexed presenter,
        uint256 indexed proposalKey
    );
    event ProposalApplied(uint256 indexed proposalKey);

    /*
        Procedure management.
    */

    function init(
        ProcedureData storage self,
        string memory cid,
        address payable proposers,
        address payable moderators,
        address payable deciders,
        bool withModeration, // Adds an extra step where moderators can block a proposal before deciders.
        address forwarder,
        address caller
    ) public {
        self.cid = cid;
        self.proposers = proposers;
        self.moderators = moderators;
        self.deciders = deciders;
        self.withModeration = withModeration;
        self.forwarder = forwarder;
        self.admin = payable(caller);
    }

    /**
        Admin API.
    */

    function updateAdmin(
        ProcedureData storage self,
        address payable admin,
        address caller
    ) public onlyInOrgan(self.admin, caller) {
        self.admin = admin;
        emit AdminUpdated(msg.sender, admin);
    }

    function updateCid(
        ProcedureData storage self,
        string memory cid,
        address caller
    ) public onlyInOrgan(self.admin, caller) {
        self.cid = cid;
        emit CidUpdated(msg.sender, cid);
    }

    /**
        Utils.
    */
    function isInOrgan(
        address payable organ,
        address caller
    ) public view returns (bool) {
        return
            organ == address(0) ||
            organ == caller ||
            IOrgan(organ).getEntryIndexForAddress(caller) != 0;
    }

    /**
        External API.
    */

    /// @notice Proposers can create a proposal with a set of operations.
    /// @dev Merge with proposalCall.
    /// @param cid Metadata describing the proposal, stored on IPFS.
    /// @param operations Set of solidity calls on the procedure or given organ.
    /// @return proposalKey of proposal created.
    function propose(
        ProcedureData storage self,
        string memory cid,
        Operation[] memory operations,
        address caller
    ) public onlyInOrgan(self.proposers, caller) returns (uint256 proposalKey) {
        proposalKey = self.proposalsLength++;
        self.proposals[proposalKey].creator = payable(caller);
        self.proposals[proposalKey].cid = cid;
        for (uint256 i = 0; i < operations.length; ++i) {
            self.proposals[proposalKey].operations.push(
                Operation({
                    index: self.proposals[proposalKey].operations.length,
                    target: operations[i].target,
                    data: operations[i].data,
                    value: operations[i].value,
                    processed: false
                })
            );
        }

        if (!self.withModeration) {
            self.proposals[proposalKey].presented = true;
        }
        emit ProposalCreated(caller, proposalKey);
        return proposalKey;
    }

    /// @notice Block proposal (veto).
    /// @param proposalKey of proposal.
    /// @param reason for blocking the proposal.
    function blockProposal(
        ProcedureData storage self,
        uint256 proposalKey,
        string memory reason,
        address caller
    ) public onlyInOrgan(self.moderators, caller) {
        require(self.withModeration, 'Moderation not enabled.');
        require(!self.proposals[proposalKey].blocked, 'Already blocked.');
        require(!self.proposals[proposalKey].applied, 'Already applied.');
        self.proposals[proposalKey].blocked = true;
        self.proposals[proposalKey].blockReason = reason;
        emit ProposalBlocked(caller, proposalKey, reason);
    }

    /// @notice Present proposal, in Moderation mode.
    /// @param proposalKey of proposal.
    function presentProposal(
        ProcedureData storage self,
        uint256 proposalKey,
        address caller
    )
        public
        onlyInOrgan(self.moderators, caller)
        onlyNewProposal(self, proposalKey)
    {
        require(self.withModeration, 'Moderation not enabled.');
        self.proposals[proposalKey].presented = true;
        emit ProposalPresented(msg.sender, proposalKey);
    }

    /// @notice Adopt proposal and attempt to apply it.
    /// @dev Should only be called once by parent contract.
    /// @param proposalKey of proposal.
    function _adoptProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) internal onlyPresentedProposal(self, proposalKey) {
        self.proposals[proposalKey].adopted = true;
        applyProposal(self, proposalKey);
    }

    /// @notice Reject proposal and mark it as applied.
    /// @dev Should only be called once by parent contract.
    /// @param proposalKey of proposal.
    function _rejectProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) internal onlyPresentedProposal(self, proposalKey) {
        self.proposals[proposalKey].adopted = false;
        self.proposals[proposalKey].applied = true;
    }

    /// @notice Apply an adopted proposal.
    /// @param proposalKey of proposal.
    function applyProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) public onlyAdoptedProposal(self, proposalKey) {
        // Process operations.
        for (
            uint256 i = 0;
            i < self.proposals[proposalKey].operations.length;
            ++i
        ) {
            if (!self.proposals[proposalKey].operations[i].processed) {
                self.proposals[proposalKey].operations[i].processed = true;
                if (
                    self.proposals[proposalKey].operations[i].target !=
                    address(0)
                ) {
                    // solhint-disable-next-line avoid-low-level-calls
                    (bool success, ) = self
                        .proposals[proposalKey]
                        .operations[i]
                        .target
                        .call{
                        value: self.proposals[proposalKey].operations[i].value
                    }(self.proposals[proposalKey].operations[i].data);
                    require(
                        success,
                        'Failed to apply proposal: the underlying transaction reverted.'
                    );
                } else {
                    // solhint-disable-next-line avoid-low-level-calls
                    (bool success, ) = address(this).call{
                        value: self.proposals[proposalKey].operations[i].value
                    }(self.proposals[proposalKey].operations[i].data);
                    require(
                        success,
                        'Failed to apply proposal: the underlying transaction reverted.'
                    );
                }
            }
        }
        self.proposals[proposalKey].applied = true;
        emit ProposalApplied(proposalKey);
    }
}

contracts/procedures/ERC20Vote.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import './Vote.sol';
import '@openzeppelin/contracts/interfaces/IERC5805.sol';

/// @title ERC20 Vote Procedure.
/// @notice An ERC20 Vote Procedure will execute operations based on the decision of a vote. The voter's relative weight in the vote depends on the amount of tokens they own of a certain asset.
contract ERC20VoteProcedure is VoteProcedure {
    /// @notice tokenContract is an ERC20Votes-compatible token representing the rights to vote.
    IERC5805 public tokenContract;

    /// @notice Prevent using the non-ERC20 initializer inherited from VoteProcedure.
    function initialize(
        string memory,
        address payable,
        address payable,
        address payable,
        bool,
        address,
        uint32,
        uint32,
        uint32
    ) public pure override {
        revert('Missing parameters');
    }

    /// @notice Initialize the procedure.
    /// @param _metadata The procedure metadata.
    /// @param _proposers The organ whose entries will be allowed to propose proposals.
    /// @param _moderators The organ whose entries will be allowed to moderate proposals.
    /// @param _deciders The organ whose entries will be allowed to adopt or refect proposals.
    /// @param _withModeration Whether or not the procedure requires moderation.
    /// @param _trustedForwarder The trusted forwarder contract.
    /// @param _quorumSize The minimum percentage of votes required to validate a election.
    /// @param _voteDuration Duration of vote in seconds.
    /// @param _majoritySize The minimum percentage of votes required to validate a election.
    /// @param _tokenContract The ERC20 token contract representing the rights to vote.
    function initialize(
        string memory _metadata,
        address payable _proposers,
        address payable _moderators,
        address payable _deciders,
        bool _withModeration,
        address _trustedForwarder,
        uint32 _quorumSize,
        uint32 _voteDuration,
        uint32 _majoritySize,
        address _tokenContract
    ) public virtual {
        require(_tokenContract.code.length > 0, 'Invalid token contract.');
        super.initialize(
            _metadata,
            _proposers,
            _moderators,
            _deciders,
            _withModeration,
            _trustedForwarder,
            _quorumSize,
            _voteDuration,
            _majoritySize
        );
        tokenContract = IERC5805(_tokenContract);
        uint48 currentClock = tokenContract.clock();
        currentClock;
    }

    function _startElection(uint256 proposalKey) internal override {
        super._startElection(proposalKey);
        uint48 currentClock = tokenContract.clock();
        require(currentClock > 0, 'Invalid token clock.');
        elections[proposalKey].snapshot = currentClock - 1;
    }

    /// @notice Count votes after election has ended.
    /// @param proposalKey The key used to identify the proposal.
    /// @return approved True if the election has been approved.
    function count(
        uint256 proposalKey
    ) public view override returns (bool approved) {
        require(elections[proposalKey].start > 0, 'No election');
        require(
            block.timestamp >= (elections[proposalKey].start + voteDuration),
            'Election not ended'
        );
        uint48 snapshot = elections[proposalKey].snapshot;
        uint256 approvals = 0;
        uint256 objections = 0;
        for (uint256 i = 0; i < elections[proposalKey].voters.length; i++) {
            address voter = elections[proposalKey].voters[i];
            if (elections[proposalKey].votes[voter].voted) {
                uint256 weight = tokenContract.getPastVotes(voter, snapshot);
                if (elections[proposalKey].votes[voter].approved) {
                    approvals += weight;
                } else {
                    objections += weight;
                }
            }
        }
        uint256 votesCast = approvals + objections;
        require(votesCast > 0, 'No vote');
        require(
            votesCast >= ((quorumSize * tokenContract.getPastTotalSupply(snapshot)) / 100000),
            'Quorum has not been reached'
        );
        return (approvals >
            ((votesCast * majoritySize) / 100000));
    }
}

