// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import '../Procedure.sol';

/// @title Nomination Procedure
/// @notice A nomination executes an operation if the nominator is in the nominaters organ.
contract NominationProcedure is Procedure {
    /// @notice function signature for nominate().
    bytes4 private constant _INTERFACE_NOMINATION = 0xc5f28e49;
    bytes32 private constant NOMINATION_TYPEHASH =
        keccak256(
            'Nomination(uint256 proposalKey,uint256 nonce,uint256 deadline)'
        );

    /// @notice Register EIP165 interfaces for introspection.
    /// @param interfaceId The interface identifier.
    /// @return isSupported True if the interface is supported, false otherwise.
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override returns (bool) {
        return
            interfaceId == _INTERFACE_NOMINATION ||
            super.supportsInterface(interfaceId);
    }

    /// @notice Apply the nomination.
    /// @param proposalKey The key used to identify the proposal.
    function nominate(
        uint256 proposalKey
    ) public onlyInOrgan(procedureData.deciders) {
        super._adoptProposal(proposalKey);
    }

    function nominateBySig(
        uint256 proposalKey,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public {
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(NOMINATION_TYPEHASH, proposalKey, nonce, deadline)
            ),
            nonce,
            deadline,
            signature
        );
        require(
            ProcedureLibrary.isInOrgan(procedureData.deciders, signer),
            'Not authorized'
        );
        super._adoptProposal(proposalKey);
    }
}

contracts/procedures/Vote.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
pragma experimental ABIEncoderV2;

import '../Procedure.sol';

struct Vote {
    bool voted;
    bool approved;
}

struct Election {
    // Map voters' addresses to votes.
    uint256 start;
    uint48 snapshot;
    mapping(address => Vote) votes;
    address[] voters;
    uint256 votesCount;
}

/// @title Vote Procedure
/// @notice  A Vote Procedure will execute operation(s) based on the decision of a vote.
/// @dev Votes can be vetoed, and enacted.
contract VoteProcedure is Procedure {
    using ProcedureLibrary for ProcedureLibrary.Operation;
    /// @notice vote().
    bytes4 private constant _INTERFACE_VOTE = 0xc9d27afe;
    bytes32 private constant VOTE_TYPEHASH =
        keccak256(
            'Vote(uint256 proposalKey,bool approval,uint256 nonce,uint256 deadline)'
        );
    mapping(uint256 => Election) internal elections;
    uint32 public quorumSize; // Minimum number of votes.
    uint32 public voteDuration; // Duration of vote in seconds.
    uint32 public majoritySize; // majoritySize.div((2^32)-1) is the minimum ratio for adoption.

    /// @dev Register EIP165 interfaces for introspection.
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override returns (bool) {
        return
            interfaceId == _INTERFACE_VOTE ||
            super.supportsInterface(interfaceId);
    }

    /// @notice Check that initialize parameters are correct.
    function initialize(
        string memory,
        address payable,
        address payable,
        address payable,
        bool,
        address
    ) public pure override {
        revert('Missing parameters');
    }

    /// @notice Initialize the procedure.
    function initialize(
        string memory _cid,
        address payable _proposers,
        address payable _moderators,
        address payable _deciders,
        bool _withModeration,
        address _trustedForwarder,
        uint32 _quorumSize,
        uint32 _voteDuration,
        uint32 _majoritySize
    ) public virtual {
        super.initialize(
            _cid,
            _proposers,
            _moderators,
            _deciders,
            _withModeration,
            _trustedForwarder
        );
        require(_voteDuration > 0, 'Invalid vote duration.');
        require(_quorumSize <= 100000, 'Invalid quorum size.');
        require(_majoritySize > 0 && _majoritySize <= 100000, 'Invalid majority size.');
        // Register EIP165 interface for introspection.
        quorumSize = _quorumSize;
        voteDuration = _voteDuration;
        majoritySize = _majoritySize;
    }

    /// @notice Create a election.
    function vote(
        uint256 proposalKey,
        bool approval
    ) public onlyInOrgan(procedureData.deciders) {
        _vote(_msgSender(), proposalKey, approval);
    }

    function voteBySig(
        uint256 proposalKey,
        bool approval,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public {
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    VOTE_TYPEHASH,
                    proposalKey,
                    approval,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        require(
            ProcedureLibrary.isInOrgan(procedureData.deciders, signer),
            'Not authorized'
        );
        _vote(signer, proposalKey, approval);
    }

    function _vote(address voter, uint256 proposalKey, bool approval) internal {
        require(
            block.timestamp > elections[proposalKey].start,
            'Election not started.'
        );
        require(
            block.timestamp < (elections[proposalKey].start + voteDuration),
            'Election ended.'
        );
        require(
            !elections[proposalKey].votes[voter].voted,
            'Duplicate record.'
        );
        elections[proposalKey].votes[voter] = Vote({
            voted: true,
            approved: approval
        });
        elections[proposalKey].voters.push(voter);
        elections[proposalKey].votesCount++;
    }

    function _startElection(uint256 proposalKey) internal virtual {
        elections[proposalKey].start = block.timestamp;
    }

    /// @notice Count votes when election is ended.
    /// @dev @todo Handle delegation of Votes.
    /// @return approved True if the proposal is adopted.
    function count(
        uint256 proposalKey
    ) public view virtual returns (bool approved) {
        require(elections[proposalKey].start > 0, 'No election.');
        require(
            block.timestamp >= (elections[proposalKey].start + voteDuration),
            'Election not ended.'
        );
        uint256 decidersCount = _getOrganEntriesCount(procedureData.deciders);
        if (
